// Task 2.2 (Logic): API route — priima ingredientus, grąžina receptus
// REQ-7: po sėkmingo generavimo automatiškai įrašo receptus į istoriją.
import { NextRequest, NextResponse } from "next/server";
import { generateRecipes } from "@/lib/generateRecipes";
import { EMPTY_PREFERENCES, UserPreferences } from "@/types/preferences";
import { resolveUserIdFromBearer, saveRecipesToHistory } from "@/lib/recipeHistory";

export async function POST(request: NextRequest) {
  let ingredients: string[];

  let excludeTitles: string[] = [];
  let preferences: UserPreferences = EMPTY_PREFERENCES;

  try {
    const body = await request.json();
    ingredients = body.ingredients;
    excludeTitles = Array.isArray(body.excludeTitles) ? body.excludeTitles : [];

    if (body.preferences && typeof body.preferences === "object") {
      preferences = {
        allergies: Array.isArray(body.preferences.allergies)
          ? body.preferences.allergies.filter((v: unknown) => typeof v === "string")
          : [],
        diets: Array.isArray(body.preferences.diets)
          ? body.preferences.diets.filter((v: unknown) => typeof v === "string")
          : [],
      };
    }
  } catch {
    return NextResponse.json(
      { error: "Neteisingas užklausos formatas." },
      { status: 400 }
    );
  }

  // AC-1: Validuojame ingredientų sąrašą
  if (!Array.isArray(ingredients) || ingredients.length === 0) {
    return NextResponse.json(
      { error: "Ingredientų sąrašas yra tuščias." },
      { status: 400 }
    );
  }

  try {
    const recipes = await generateRecipes(ingredients, excludeTitles, preferences);

    // REQ-7: Įrašome į istoriją, jei vartotojas prisijungęs (turi Bearer tokeną).
    // Klaida čia neturi nutraukti atsakymo — istorija yra papildoma funkcija.
    try {
      const userId = await resolveUserIdFromBearer(request.headers.get("authorization"));
      if (userId) {
        await saveRecipesToHistory(userId, recipes);
      }
    } catch (historyError) {
      console.error("[generate-recipe] Istorijos įrašymo klaida:", historyError);
    }

    return NextResponse.json({ recipes });
  } catch (error) {
    // AC-4: Klaida registruojama žurnale
    console.error("[generate-recipe] Klaida:", error);

    const isTimeout =
      error instanceof Error && error.message.includes("timeout");

    return NextResponse.json(
      {
        error: isTimeout
          ? "Užklausa užtruko per ilgai. Bandykite dar kartą."
          : "Nepavyko sugeneruoti receptų. Bandykite dar kartą.",
      },
      { status: 500 }
    );
  }
}

// Task 3.2 (Logic): API route receptų išsaugojimui
import { NextRequest, NextResponse } from "next/server";
import { supabaseServer } from "@/lib/supabase";
import { Recipe } from "@/types/recipe";

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { recipe }: { recipe: Recipe } = body;

    // Validacija
    if (!recipe || !recipe.title || !recipe.ingredients) {
      return NextResponse.json(
        { error: "Neteisingi recepto duomenys." },
        { status: 400 }
      );
    }

    // Check if Supabase is configured
    if (!process.env.NEXT_PUBLIC_SUPABASE_URL || !process.env.SUPABASE_SERVICE_ROLE_KEY) {
      // For demo purposes, simulate successful save
      return NextResponse.json({
        success: true,
        message: "Receptas išsaugotas! (Demo režimas)",
        recipe: {
          id: Date.now(),
          user_id: "demo-user",
          title: recipe.title,
          ingredients: recipe.ingredients,
          steps: recipe.steps,
          calories: recipe.estimated_calories,
        }
      });
    }

    // AC-2: Patikrinti dublikatus (UNIQUE constraint ant (user_id, title))
    // Šiuo metu nėra autentifikacijos, todėl naudojame fiktyvų user_id
    // Ateityje čia bus realus user_id iš sesijos
    const userId = "demo-user"; // Placeholder

    const { data: existingRecipe, error: checkError } = await supabaseServer
      .from("saved_recipes")
      .select("id")
      .eq("user_id", userId)
      .eq("title", recipe.title)
      .single();

    if (checkError && checkError.code !== "PGRST116") { // PGRST116 = not found
      console.error("Klaida tikrinant dublikatus:", checkError);
      return NextResponse.json(
        { error: "Nepavyko patikrinti dublikatų." },
        { status: 500 }
      );
    }

    if (existingRecipe) {
      return NextResponse.json(
        { error: "Šis receptas jau išsaugotas." },
        { status: 409 }
      );
    }

    // AC-3: Įrašyti receptą į duomenų bazę
    const { data, error } = await supabaseServer
      .from("saved_recipes")
      .insert({
        user_id: userId,
        title: recipe.title,
        ingredients: recipe.ingredients,
        steps: recipe.steps,
        calories: recipe.estimated_calories,
        servings: recipe.servings,
        missing_ingredients: recipe.missing_ingredients,
      })
      .select()
      .single();

    if (error) {
      console.error("Klaida įrašant receptą:", error);
      return NextResponse.json(
        { error: "Nepavyko išsaugoti recepto." },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      message: "Receptas išsaugotas!",
      recipe: data
    });

  } catch (error) {
    console.error("Serverio klaida:", error);
    return NextResponse.json(
      { error: "Serverio klaida." },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { supabaseServer } from '@/lib/supabase';
import { Recipe } from '@/types/recipe';

const mockSavedRecipes: Recipe[] = [
  {
    title: "Klasikinis keptas viščiukas su daržovėmis",
    servings: 4,
    ingredients: ["viščiukas 1kg", "bulvės 500g", "morkos 200g", "svogūnai 2vnt", "alyvuogių aliejus 2š"],
    steps: [
