"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import RecipeCard from "@/components/RecipeCard";
import { Recipe } from "@/types/recipe";
import { RecipeHistoryEntry } from "@/types/recipeHistory";
import { supabase } from "@/lib/supabase";

const isDemo =
  !process.env.NEXT_PUBLIC_SUPABASE_URL ||
  process.env.NEXT_PUBLIC_SUPABASE_URL === "https://demo.supabase.co";

const HISTORY_STORAGE_KEY = "recipeHistory";
const SAVED_RECIPES_KEY = "savedRecipes";

function formatDate(iso: string): string {
  try {
    const date = new Date(iso);
    return date.toLocaleString("lt-LT", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return iso;
  }
}

export default function HistoryPage() {
  const router = useRouter();
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [history, setHistory] = useState<RecipeHistoryEntry[]>([]);
  const [selected, setSelected] = useState<RecipeHistoryEntry | null>(null);
  const [savedRecipes, setSavedRecipes] = useState<Recipe[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function init() {
      const { data } = await supabase.auth.getSession();
      if (!data.session) {
        router.replace("/login");
        return;
      }
      setUserEmail(data.session.user.email ?? null);
      await loadHistory(data.session.access_token);
      loadSavedRecipesLocal();
      setIsLoading(false);
    }
    init();
  }, [router]);

  async function loadHistory(accessToken: string) {
    if (isDemo) {
      try {
        const raw = localStorage.getItem(HISTORY_STORAGE_KEY);
        const parsed = raw ? (JSON.parse(raw) as RecipeHistoryEntry[]) : [];
        setHistory(parsed);
      } catch {
        setHistory([]);
      }
      return;
    }
    try {
      const response = await fetch("/api/recipes/history", {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      if (!response.ok) {
        setError("Nepavyko įkelti istorijos.");
        return;
      }
      const data = await response.json();
      setHistory(Array.isArray(data.history) ? data.history : []);
    } catch {
      setError("Nepavyko įkelti istorijos.");
    }
  }

  function loadSavedRecipesLocal() {
    if (!isDemo) return;
    try {
      const raw = localStorage.getItem(SAVED_RECIPES_KEY);
      if (raw) setSavedRecipes(JSON.parse(raw));
    } catch {
      // ignoruoti
    }
  }

  function handleToggleSave(recipe: Recipe) {
    const isCurrentlySaved = savedRecipes.some((r) => r.title === recipe.title);
    const newSaved = isCurrentlySaved
      ? savedRecipes.filter((r) => r.title !== recipe.title)
      : [...savedRecipes, recipe];
    setSavedRecipes(newSaved);

    if (isDemo) {
      try {
        localStorage.setItem(SAVED_RECIPES_KEY, JSON.stringify(newSaved));
      } catch {
        // ignoruoti
      }
      return;
    }
    const endpoint = isCurrentlySaved ? "/api/recipes/unsave" : "/api/recipes/save";
    fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ recipe }),
    }).catch(() => {
      // ignoruoti — UI būsena jau atnaujinta
    });
  }

  return (
    <div className="min-h-screen bg-zinc-50 font-sans dark:bg-zinc-950">
      <main className="mx-auto w-full max-w-3xl px-4 py-12 sm:px-8">
        <div className="mb-8 flex items-start justify-between gap-2">
          <div>
            <h1 className="text-2xl font-bold text-zinc-900 dark:text-zinc-50">📜 Istorija</h1>
            <p className="mt-1 text-sm text-zinc-500 dark:text-zinc-400">
              Paskutiniai 10 sugeneruotų receptų.
            </p>
          </div>
          <div className="text-right">
            {userEmail && (
              <p className="text-xs text-zinc-400 dark:text-zinc-500 truncate max-w-35">{userEmail}</p>
            )}
            <Link
              href="/"
              className="text-xs text-zinc-600 hover:text-zinc-900 dark:text-zinc-300 dark:hover:text-zinc-100"
            >
              ← Grįžti į pradžią
            </Link>
          </div>
        </div>

        {isLoading && (
          <p className="text-sm text-zinc-500 dark:text-zinc-400">Įkeliama...</p>
        )}

        {!isLoading && error && (
          <p className="text-sm text-red-600 dark:text-red-400" role="alert">
            {error}
          </p>
        )}

        {!isLoading && !error && history.length === 0 && (
          <p className="text-sm text-zinc-500 dark:text-zinc-400">
            Istorija tuščia. Sugeneruokite bent vieną receptą pradžios puslapyje.
          </p>
        )}

        {!isLoading && history.length > 0 && (
          <ul className="space-y-2" data-testid="history-list">
            {history.map((entry) => (
              <li key={entry.id}>
                <button
                  type="button"
                  onClick={() => setSelected(entry)}
                  className="w-full rounded-lg border border-zinc-200 bg-white px-4 py-3 text-left transition-colors hover:border-green-500 hover:bg-green-50 dark:border-zinc-800 dark:bg-zinc-900 dark:hover:border-green-600 dark:hover:bg-zinc-800"
                  data-testid="history-item"
                >
                  <div className="flex items-center justify-between gap-3">
                    <span className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                      {entry.title}
                    </span>
                    <span className="text-xs text-zinc-500 dark:text-zinc-400">
                      {formatDate(entry.createdAt)}
                    </span>
                  </div>
                </button>
              </li>
            ))}
          </ul>
        )}
      </main>

      {selected && (
        <div
          className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/50 p-4 sm:items-center"
          onClick={() => setSelected(null)}
          data-testid="recipe-modal-backdrop"
          role="dialog"
          aria-modal="true"
          aria-label={`Receptas: ${selected.title}`}
        >
          <div
            className="relative w-full max-w-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              type="button"
              onClick={() => setSelected(null)}
              className="absolute right-2 top-2 z-10 flex h-9 w-9 items-center justify-center rounded-full bg-white text-zinc-700 shadow-md hover:bg-zinc-100 dark:bg-zinc-800 dark:text-zinc-200 dark:hover:bg-zinc-700"
              aria-label="Uždaryti"
            >
              ✕
            </button>
            <RecipeCard
              recipe={selected.recipe}
              isSaved={savedRecipes.some((r) => r.title === selected.recipe.title)}
              onToggleSave={() => handleToggleSave(selected.recipe)}
            />
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Search, Bookmark, ChefHat, AlertCircle, LogOut, BookmarkPlus, History, Settings } from "lucide-react";
import IngredientInput from "@/components/IngredientInput";
import IngredientList from "@/components/IngredientList";
import RecipeCard from "@/components/RecipeCard";
import { Recipe } from "@/types/recipe";
import { EMPTY_PREFERENCES, UserPreferences } from "@/types/preferences";
import { MAX_HISTORY_PER_USER, RecipeHistoryEntry } from "@/types/recipeHistory";
import { supabase } from "@/lib/supabase";

const isDemo = !process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL === 'https://demo.supabase.co';
const PREFERENCES_STORAGE_KEY = "userPreferences";
const HISTORY_STORAGE_KEY = "recipeHistory";

export default function Home() {
  const router = useRouter();
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [editingIngredient, setEditingIngredient] = useState<string | null>(null);
  const [recipes, setRecipes] = useState<Recipe[] | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [savedRecipes, setSavedRecipes] = useState<Recipe[]>([]);
  const [showSaved, setShowSaved] = useState(false);
  const [preferences, setPreferences] = useState<UserPreferences>(EMPTY_PREFERENCES);
  const lastRequestRef = useRef<number>(0);
  const RATE_LIMIT_MS = 10000;

  function handleAddIngredient(ingredient: string) {
    setIngredients((prev) => [...prev, ingredient]);
  }

  function handleRemoveIngredient(ingredient: string) {
    setIngredients((prev) => prev.filter((i) => i !== ingredient));
  }

  function handleRemoveAllIngredients() {
    setIngredients([]);
  }

  function handleEditIngredient(ingredient: string) {
    setEditingIngredient(ingredient);
  }

  function handleReplaceIngredient(oldIngredient: string, newIngredient: string) {
    setIngredients((prev) => prev.map((i) => (i === oldIngredient ? newIngredient : i)));
    setEditingIngredient(null);
  }

  async function handleGenerateRecipes() {
    const now = Date.now();
    const elapsed = now - lastRequestRef.current;

    if (elapsed < RATE_LIMIT_MS && lastRequestRef.current !== 0) {
      const remaining = Math.ceil((RATE_LIMIT_MS - elapsed) / 1000);
      setError(`Per dažnai spaudžiate mygtuką. Palaukite dar ${remaining} sek.`);
      return;
    }

    lastRequestRef.current = now;
    setIsLoading(true);
    setError(null);

    const excludeTitles = recipes ? recipes.map((r) => r.title) : [];

    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const accessToken = sessionData.session?.access_token;

      const headers: Record<string, string> = { "Content-Type": "application/json" };
      if (accessToken) {
        headers.Authorization = `Bearer ${accessToken}`;
      }

      const response = await fetch("/api/generate-recipe", {
        method: "POST",
        headers,
        body: JSON.stringify({ ingredients, excludeTitles, preferences }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error ?? "Nepavyko sugeneruoti receptų.");
      }

      const newRecipes: Recipe[] = data.recipes;

      if (!newRecipes || newRecipes.length === 0) {
        setError("Naujų receptų nerasta. Pabandykite pakeisti ingredientus.");
        return;
      }

      setRecipes(newRecipes);
      setShowSaved(false);

      // REQ-7: Demo režime istorija saugoma vietinėje saugykloje (max 10 naujausių).
      if (isDemo) {
        try {
          const raw = localStorage.getItem(HISTORY_STORAGE_KEY);
          const existing: RecipeHistoryEntry[] = raw ? JSON.parse(raw) : [];
          const now = new Date().toISOString();
          const newEntries: RecipeHistoryEntry[] = newRecipes.map((recipe) => ({
            id: `${Date.now()}-${recipe.title}`,
            title: recipe.title,
            recipe,
            createdAt: now,
          }));
          const combined = [...newEntries, ...existing].slice(0, MAX_HISTORY_PER_USER);
          localStorage.setItem(HISTORY_STORAGE_KEY, JSON.stringify(combined));
        } catch {
          // ignoruoti — istorija yra papildoma funkcija
        }
      }
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Nepavyko sugeneruoti receptų.";
      setError(message);
    } finally {
      setIsLoading(false);
    }
  }

  async function handleShowSavedRecipes() {
    setError(null);
    await loadSavedRecipes();
    setShowSaved(true);
  }

  async function loadSavedRecipes() {
    if (isDemo) {
      const stored = localStorage.getItem('savedRecipes');
      if (stored) {
        setSavedRecipes(JSON.parse(stored));
      } else {
        setSavedRecipes([]);
      }
    } else {
      try {
        const response = await fetch("/api/recipes/saved");
        const data = await response.json();
        if (response.ok) {
          setSavedRecipes(data.recipes);
        } else {
          setError(data.error ?? "Nepavyko įkelti išsaugotų receptų.");
        }
      } catch (err) {
        setError("Nepavyko įkelti išsaugotų receptų.");
      }
    }
  }

  function handleToggleSave(recipe: Recipe) {
    const isCurrentlySaved = savedRecipes.some(r => r.title === recipe.title);
    if (isCurrentlySaved) {
      const newSaved = savedRecipes.filter(r => r.title !== recipe.title);
      setSavedRecipes(newSaved);
      if (isDemo) {
        localStorage.setItem('savedRecipes', JSON.stringify(newSaved));
      } else {
        fetch('/api/recipes/unsave', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ recipe }),
        });
      }
    } else {
      const newSaved = [...savedRecipes, recipe];
      setSavedRecipes(newSaved);
      if (isDemo) {
        localStorage.setItem('savedRecipes', JSON.stringify(newSaved));
      } else {
        fetch('/api/recipes/save', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ recipe }),
        });
      }
    }
  }

  async function loadPreferences(accessToken: string) {
    if (isDemo) {
      try {
        const raw = localStorage.getItem(PREFERENCES_STORAGE_KEY);
        if (raw) setPreferences(JSON.parse(raw) as UserPreferences);
      } catch {
        // ignoruoti
      }
      return;
    }
    try {
      const response = await fetch("/api/user/preferences", {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      if (!response.ok) return;
      const data = await response.json();
      setPreferences({
        allergies: Array.isArray(data.allergies) ? data.allergies : [],
        diets: Array.isArray(data.diets) ? data.diets : [],
      });
    } catch {
      // ignoruoti — receptai vis tiek generuosis be filtrų
    }
  }

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      if (!data.session) {
        router.replace("/login");
        return;
      }
      setUserEmail(data.session.user.email ?? null);
      loadSavedRecipes();
      loadPreferences(data.session.access_token);
    });
  }, []);

  async function handleLogout() {
    await supabase.auth.signOut();
    router.push("/login");
  }

  const hasRecipes = recipes !== null;
  const hasContent = hasRecipes || showSaved || isLoading;
  const displayedRecipes = showSaved ? savedRecipes : recipes;
  const showSavedEmpty = showSaved && savedRecipes.length === 0 && !isLoading;

  return (
    <div className="min-h-screen bg-[var(--bg)] text-[var(--ink)]">
      <div
        className={`flex min-h-screen ${
          hasContent
            ? "flex-col lg:flex-row items-start"
            : "items-start justify-center"
        }`}
      >
        {/* Kairė pusė — ingredientai */}
        <main
          className={`px-5 py-10 sm:px-8 ${
            hasContent
              ? "w-full lg:w-96 xl:w-[26rem] lg:min-h-screen lg:border-r border-[var(--border)] shrink-0"
              : "w-full max-w-2xl"
          }`}
        >
          {/* Header */}
          <div className="mb-10">
            <div className="flex items-start justify-between gap-2">
              <div className="flex items-center gap-2.5">
                <span
                  className="inline-flex h-10 w-10 items-center justify-center rounded-xl bg-[var(--primary)]/12 text-[var(--primary)]"
                  aria-hidden
                >
                  <ChefHat size={22} strokeWidth={2} />
                </span>
                <h1 className="font-display text-3xl font-semibold leading-none text-[var(--ink)]">
                  Fridge Chef
                </h1>
              </div>
              {userEmail && (
                <div className="text-right">
                  <p className="max-w-[10rem] truncate text-xs text-[var(--ink-muted)]">{userEmail}</p>
                  <div className="mt-1 flex items-center justify-end gap-2.5 text-xs">
                    <Link
                      href="/history"
                      className="inline-flex items-center gap-1 text-[var(--ink-muted)] transition-colors hover:text-[var(--primary)]"
                    >
                      <History size={11} aria-hidden />
                      Istorija
                    </Link>
                    <span className="text-[var(--border)]" aria-hidden>•</span>
                    <Link
                      href="/settings"
                      className="inline-flex items-center gap-1 text-[var(--ink-muted)] transition-colors hover:text-[var(--primary)]"
                    >
                      <Settings size={11} aria-hidden />
                      Nustatymai
                    </Link>
                    <span className="text-[var(--border)]" aria-hidden>•</span>
                    <button
                      type="button"
                      onClick={handleLogout}
                      className="inline-flex items-center gap-1 text-[var(--ink-muted)] transition-colors hover:text-[var(--saved)]"
                    >
                      <LogOut size={11} aria-hidden />
                      Atsijungti
                    </button>
                  </div>
                </div>
              )}
            </div>
            <p className="mt-3 text-sm leading-relaxed text-[var(--ink-muted)]">
              Įveskite turimus ingredientus ir gaukite receptų pasiūlymus.
            </p>
          </div>

          {/* Ingredientų įvedimas (REQ-1) */}
          <section className="mb-8">
            <h2 className="font-display mb-4 text-xl font-semibold text-[var(--ink)]">
              Mano ingredientai
            </h2>
            <IngredientInput
              onAdd={handleAddIngredient}
              addedIngredients={ingredients}
              editingIngredient={editingIngredient}
              onReplace={handleReplaceIngredient}
            />
          </section>

          {/* Pridėtų ingredientų sąrašas */}
          <section>
            <h2 className="mb-3 text-xs font-semibold uppercase tracking-wider text-[var(--ink-muted)]">
              Pridėti ingredientai ({ingredients.length})
            </h2>
            <IngredientList
              ingredients={ingredients}
              onRemove={handleRemoveIngredient}
              onRemoveAll={handleRemoveAllIngredients}
              onEdit={handleEditIngredient}
            />
          </section>

          {/* Primary CTA — generate */}
          {ingredients.length > 0 && (
            <div className="mt-8 space-y-2">
              <button
                type="button"
                onClick={handleGenerateRecipes}
                disabled={isLoading || ingredients.length === 0}
                className={`inline-flex w-full max-w-md items-center justify-center gap-2 rounded-lg px-6 py-3 text-sm font-semibold transition-all ${
                  isLoading || ingredients.length === 0
                    ? "cursor-not-allowed bg-[var(--border)] text-[var(--ink-muted)]"
                    : "bg-[var(--primary)] text-white shadow-[0_4px_14px_rgba(198,107,61,0.25)] hover:bg-[var(--primary-hover)] hover:shadow-[0_6px_18px_rgba(198,107,61,0.32)] active:translate-y-px"
                }`}
              >
                {isLoading ? (
                  <>
                    <span className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-white/70 border-t-transparent" />
                    Generuojama...
                  </>
                ) : (
                  <>
                    <Search size={16} aria-hidden />
                    Ieškoti receptų
                  </>
                )}
              </button>

              {error && (
                <div
                  className="flex items-start gap-2 rounded-lg border border-[var(--primary)]/25 bg-[var(--danger-soft)] px-3 py-2 text-sm text-[var(--danger)]"
                  role="alert"
                >
                  <AlertCircle size={16} className="mt-0.5 shrink-0" aria-hidden />
                  <span>{error}</span>
                </div>
              )}
            </div>
          )}

          {/* Secondary nav — show generated/saved (ghost style) */}
          <div className="mt-6 grid w-full max-w-md grid-cols-1 gap-2 sm:grid-cols-2">
            {(hasRecipes || showSaved) && (
              <button
                type="button"
                onClick={() => setShowSaved(false)}
                disabled={!hasRecipes}
                className={`inline-flex items-center justify-center gap-2 rounded-lg border px-4 py-2.5 text-sm font-medium transition-colors ${
                  !showSaved
                    ? "border-[var(--primary)]/40 bg-[var(--primary)]/8 text-[var(--primary)]"
                    : "border-[var(--border)] bg-transparent text-[var(--ink)] hover:border-[var(--primary)]/30 hover:text-[var(--primary)]"
                } ${!hasRecipes ? "cursor-not-allowed opacity-50" : ""}`}
              >
                <Search size={14} aria-hidden />
                Sugeneruoti
              </button>
            )}
            <button
              type="button"
              onClick={handleShowSavedRecipes}
              className={`inline-flex items-center justify-center gap-2 rounded-lg border px-4 py-2.5 text-sm font-medium transition-colors ${
                showSaved
                  ? "border-[var(--saved)]/40 bg-[var(--saved)]/10 text-[var(--saved)]"
                  : "border-[var(--border)] bg-transparent text-[var(--ink)] hover:border-[var(--saved)]/30 hover:text-[var(--saved)]"
              } ${!(hasRecipes || showSaved) ? "sm:col-span-2" : ""}`}
            >
              <Bookmark size={14} aria-hidden />
              Išsaugoti
            </button>
          </div>
        </main>

        {/* Dešinė pusė — receptai (kai sugeneruota, įkeliama arba išsaugoti) */}
        {hasContent && (
          <section className="flex-1 px-5 py-10 sm:px-8">
            <h2 className="font-display mb-6 text-2xl font-semibold text-[var(--ink)]">
              {isLoading
                ? "Generuojami receptai..."
                : showSaved
                ? `Išsaugoti receptai (${savedRecipes.length})`
                : `Sugeneruoti receptai (${recipes?.length || 0})`}
            </h2>

            {isLoading ? (
              <div className="grid grid-cols-1 gap-6 xl:grid-cols-2">
                {[0, 1, 2].map((i) => (
                  <RecipeSkeleton key={i} />
                ))}
              </div>
            ) : showSavedEmpty ? (
              <EmptySaved />
            ) : (
              <div className="grid grid-cols-1 gap-6 xl:grid-cols-2">
                {displayedRecipes?.map((recipe, index) => (
                  <RecipeCard
                    key={index}
                    recipe={recipe}
                    isSaved={savedRecipes.some(r => r.title === recipe.title)}
                    onToggleSave={() => handleToggleSave(recipe)}
                  />
                ))}
              </div>
            )}
          </section>
        )}
      </div>
    </div>
  );
}

function RecipeSkeleton() {
  return (
    <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-6 shadow-[0_2px_12px_rgba(166,124,82,0.06)]">
      <div className="mb-4 flex items-start justify-between gap-4">
        <div className="skeleton h-7 w-2/3 rounded-md" />
        <div className="skeleton h-10 w-10 rounded-full" />
      </div>
      <div className="skeleton mb-5 h-4 w-1/3 rounded-md" />
      <div className="mb-5 space-y-2">
        <div className="skeleton h-3 w-full rounded-md" />
        <div className="skeleton h-3 w-5/6 rounded-md" />
        <div className="skeleton h-3 w-4/6 rounded-md" />
      </div>
      <div className="space-y-2">
        <div className="skeleton h-3 w-full rounded-md" />
        <div className="skeleton h-3 w-3/4 rounded-md" />
      </div>
    </div>
  );
}

function EmptySaved() {
  return (
    <div className="flex flex-col items-center justify-center rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)]/40 px-6 py-16 text-center">
      <span
        className="mb-3 inline-flex h-12 w-12 items-center justify-center rounded-full bg-[var(--saved)]/10 text-[var(--saved)]"
        aria-hidden
      >
        <BookmarkPlus size={22} />
      </span>
      <p className="font-display text-lg font-semibold text-[var(--ink)]">
        Dar neturite išsaugotų receptų
      </p>
      <p className="mt-1 max-w-sm text-sm text-[var(--ink-muted)]">
        Sugeneravę receptą, paspauskite širdelę, kad jį išsaugotumėte į savo kolekciją.
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { supabase } from "@/lib/supabase";
import Link from "next/link";
import { ChefHat, AlertCircle, MailCheck } from "lucide-react";

function translateAuthError(message: string): string {
  if (message.includes("User already registered")) return "Šis el. paštas jau užregistruotas.";
  if (message.includes("already registered")) return "Šis el. paštas jau užregistruotas.";
  if (message.includes("Password should be at least")) return "Slaptažodis turi būti bent 6 simbolių.";
  if (message.includes("Unable to validate email")) return "Neteisingas el. pašto formatas.";
  if (message.includes("invalid email")) return "Neteisingas el. pašto formatas.";
  if (message.includes("Too many requests")) return "Per daug bandymų. Palaukite ir bandykite vėliau.";
  if (message.includes("rate limit")) return "Per daug bandymų. Palaukite ir bandykite vėliau.";
  if (message.includes("Email rate limit")) return "Viršyta el. pašto siuntimo riba. Bandykite vėliau.";
  if (message.includes("Signups not allowed")) return "Registracija šiuo metu išjungta.";
  if (message.includes("not allowed")) return "Registracija šiuo metu išjungta.";
  if (message.includes("weak password") || message.includes("Password")) return "Slaptažodis per silpnas.";
  return `Registracijos klaida: ${message}`;
}

const fieldClass =
  "w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-4 py-2.5 text-sm text-[var(--ink)] placeholder-[var(--ink-muted)]/70 transition-colors focus:border-[var(--primary)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)]/25";

export default function RegisterPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  async function handleRegister(e: React.FormEvent) {
    e.preventDefault();
    setError(null);

    if (password !== confirmPassword) {
      setError("Slaptažodžiai nesutampa.");
      return;
    }

    if (password.length < 6) {
      setError("Slaptažodis turi būti bent 6 simbolių.");
      return;
    }

    if (password.length > 30) {
      setError("Slaptažodis negali būti ilgesnis nei 30 simbolių.");
      return;
    }

    if (password.toLowerCase() == password) {
      setError("Slaptažodis turi turėti bent 1 didžiąją raidę.");
      return;
    }

    if (!/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
      setError("Slaptažodis turi turėti bent vieną specialų simbolį (pvz. !@#$%).");
      return;
    }

    setIsLoading(true);

    const { error } = await supabase.auth.signUp({ email, password });

    if (error) {
      setError(translateAuthError(error.message));
      setIsLoading(false);
      return;
    }

    setSuccess(true);
    setIsLoading(false);
  }

  if (success) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[var(--bg)] px-4 py-10">
        <div className="w-full max-w-sm text-center">
          <span
            className="mx-auto mb-4 inline-flex h-14 w-14 items-center justify-center rounded-2xl bg-[var(--secondary-soft)] text-[var(--secondary)]"
            aria-hidden
          >
            <MailCheck size={28} />
          </span>
          <h2 className="font-display text-2xl font-semibold text-[var(--ink)]">
            Patikrinkite el. paštą
          </h2>
          <p className="mt-2 text-sm text-[var(--ink-muted)]">
            Išsiuntėme patvirtinimo nuorodą į <strong className="text-[var(--ink)]">{email}</strong>.
            Paspauskite joje esančią nuorodą, kad aktyvuotumėte paskyrą.
          </p>
          <Link
            href="/login"
            className="mt-6 inline-block text-sm font-medium text-[var(--primary)] hover:text-[var(--primary-hover)]"
          >
            ← Grįžti į prisijungimą
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-[var(--bg)] px-4 py-10">
      <div className="w-full max-w-sm">
        <div className="mb-8 flex flex-col items-center text-center">
          <span
            className="mb-3 inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-[var(--primary)]/12 text-[var(--primary)]"
            aria-hidden
          >
            <ChefHat size={26} />
          </span>
          <h1 className="font-display text-3xl font-semibold text-[var(--ink)]">
            Fridge Chef
          </h1>
          <p className="mt-1 text-sm text-[var(--ink-muted)]">
            Sukurkite naują paskyrą
          </p>
        </div>

        <form
          onSubmit={handleRegister}
          className="space-y-4 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-6 shadow-[0_2px_12px_rgba(166,124,82,0.06)]"
        >
          <div>
            <label
              htmlFor="email"
              className="mb-1 block text-sm font-medium text-[var(--ink)]"
            >
              El. paštas
            </label>
            <input
              id="email"
              type="email"
              required
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className={fieldClass}
              placeholder="jusu@pastas.lt"
            />
          </div>

          <div>
            <label
              htmlFor="password"
              className="mb-1 block text-sm font-medium text-[var(--ink)]"
            >
              Slaptažodis
            </label>
            <input
              id="password"
              type="password"
              required
              autoComplete="new-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className={fieldClass}
              placeholder="••••••••"
            />
          </div>

          <div>
            <label
              htmlFor="confirmPassword"
              className="mb-1 block text-sm font-medium text-[var(--ink)]"
            >
              Pakartokite slaptažodį
            </label>
            <input
              id="confirmPassword"
              type="password"
              required
              autoComplete="new-password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className={fieldClass}
              placeholder="••••••••"
            />
          </div>

          {error && (
            <div
              className="flex items-start gap-2 rounded-lg border border-[var(--primary)]/25 bg-[var(--danger-soft)] px-3 py-2 text-sm text-[var(--danger)]"
              role="alert"
            >
              <AlertCircle size={16} className="mt-0.5 shrink-0" aria-hidden />
              <span>{error}</span>
            </div>
          )}

          <button
            type="submit"
            disabled={isLoading}
            className={`w-full rounded-lg px-5 py-2.5 text-sm font-semibold transition-all ${
              isLoading
                ? "cursor-not-allowed bg-[var(--border)] text-[var(--ink-muted)]"
                : "bg-[var(--primary)] text-white shadow-[0_4px_14px_rgba(198,107,61,0.25)] hover:bg-[var(--primary-hover)] active:translate-y-px"
            }`}
          >
            {isLoading ? "Kuriama paskyra..." : "Registruotis"}
          </button>
        </form>

        <p className="mt-6 text-center text-sm text-[var(--ink-muted)]">
          Jau turite paskyrą?{" "}
          <Link
            href="/login"
            className="font-medium text-[var(--primary)] hover:text-[var(--primary-hover)]"
          >
            Prisijungti
          </Link>
        </p>
      </div>
    </div>
  );
}

